import React, { useState, useEffect } from 'react';
import api from '../api';

const InteractiveSeating = ({ event, user, onBack, onCheckoutSuccess, showToast }) => {
    const [seats, setSeats] = useState([]);
    const [secondsLeft, setSecondsLeft] = useState(0);
    const [paymentMethod, setPaymentMethod] = useState('card');

    const fetchSeats = async () => {
        try {
            const res = await api.get(`/events/${event.id}/seats`);
            setSeats(res.data);
        } catch (err) {
            showToast('Failed to load seating chart', 'error');
        }
    };

    useEffect(() => {
        fetchSeats();
    }, [event.id]);

    const myLockedSeats = seats.filter(s => s.status === 'LOCKED' && s.lockedByUserId === user.id);

    useEffect(() => {
        if (myLockedSeats.length === 0) {
            setSecondsLeft(0);
            return;
        }
        setSecondsLeft(300);
        const timer = setInterval(() => {
            setSecondsLeft(prev => {
                if (prev <= 1) {
                    clearInterval(timer);
                    fetchSeats();
                    showToast('Temporary seat lock expired (TTL 05:00).', 'warning');
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        return () => clearInterval(timer);
    }, [myLockedSeats.length]);

    const handleSeatClick = async (seat) => {
        if (seat.status === 'SOLD') return;
        if (seat.status === 'LOCKED' && seat.lockedByUserId !== user.id) {
            showToast('Seat is currently locked by another user.', 'warning');
            return;
        }
        if (seat.status === 'AVAILABLE' && myLockedSeats.length >= 6) {
            showToast('Maximum 6 seats can be locked per transaction.', 'warning');
            return;
        }
        try {
            await api.post(`/seats/${seat.id}/toggle-lock`);
            await fetchSeats();
        } catch (err) {
            showToast(err.response?.data?.message || 'Seat unavailable', 'error');
            fetchSeats();
        }
    };

    const handleCheckout = async () => {
        try {
            const seatIds = myLockedSeats.map(s => s.id);
            const res = await api.post('/orders/checkout', { eventId: event.id, seatIds, paymentMethod });
            showToast(`Payment confirmed! ${res.data.issuedCount} cryptographic QR ticket(s) issued.`, 'success');
            onCheckoutSuccess();
        } catch (err) {
            showToast(err.response?.data?.message || 'Checkout failed', 'error');
        }
    };

    const rows = ['A', 'B', 'C', 'D', 'E', 'F'];
    const totalAmount = myLockedSeats.reduce((sum, s) => sum + s.price, 0);
    const mins = String(Math.floor(secondsLeft / 60)).padStart(2, '0');
    const secs = String(secondsLeft % 60).padStart(2, '0');

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4 bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5">
                <div className="flex items-center gap-3">
                    <button onClick={onBack} className="p-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 transition">←</button>
                    <div>
                        <div className="flex items-center gap-2">
                            <h2 className="text-lg sm:text-xl font-bold text-white">{event.title}</h2>
                            <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-cyan-500/15 text-cyan-400 border border-cyan-500/30">{event.category}</span>
                        </div>
                        <p className="text-xs sm:text-sm text-slate-400">{event.venue} • {event.date}</p>
                    </div>
                </div>

                {myLockedSeats.length > 0 && (
                    <div className="flex items-center gap-3 px-4 py-2.5 rounded-xl bg-amber-500/10 border border-amber-500/40">
                        <div className="w-2.5 h-2.5 rounded-full bg-amber-400 animate-ping"></div>
                        <div>
                            <p className="text-[11px] uppercase tracking-wider font-semibold text-amber-300">DB Row Lock Active (TTL)</p>
                            <p className="font-mono text-lg font-extrabold text-amber-400">{mins}:{secs}</p>
                        </div>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-slate-900 border border-slate-800 rounded-2xl p-5 sm:p-6 flex flex-col justify-between">
                    <div>
                        <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
                            <h3 className="font-bold text-white">Interactive Venue Seating Map</h3>
                            <div className="flex flex-wrap items-center gap-3 text-xs">
                                <span className="flex items-center gap-1.5"><span className="w-3.5 h-3.5 rounded bg-amber-500/80 border border-amber-300 inline-block"></span> VIP</span>
                                <span className="flex items-center gap-1.5"><span className="w-3.5 h-3.5 rounded bg-cyan-500/80 border border-cyan-300 inline-block"></span> Golden</span>
                                <span className="flex items-center gap-1.5"><span className="w-3.5 h-3.5 rounded bg-slate-700 border border-slate-500 inline-block"></span> General</span>
                                <span className="flex items-center gap-1.5"><span className="w-3.5 h-3.5 rounded bg-emerald-500 border border-white inline-block"></span> Selected</span>
                            </div>
                        </div>

                        <div className="my-4">
                            <div className="w-4/5 mx-auto h-10 rounded-t-full bg-gradient-to-b from-cyan-500/30 to-transparent border-t-2 border-cyan-400 flex items-center justify-center">
                                <span className="text-xs font-mono font-bold tracking-[0.25em] text-cyan-300 uppercase">MAIN STAGE &amp; AUDIO RIG</span>
                            </div>
                        </div>

                        <div className="space-y-2.5 max-w-xl mx-auto py-3 overflow-x-auto">
                            {rows.map(rowChar => {
                                const rowSeats = seats.filter(s => s.seatIdentifier.startsWith(rowChar));
                                if (rowSeats.length === 0) return null;
                                return (
                                    <div key={rowChar} className="flex items-center justify-center gap-2">
                                        <span className="w-6 text-xs font-mono font-bold text-slate-500 text-right">{rowChar}</span>
                                        <div className="flex items-center gap-1.5">
                                            {rowSeats.map((s, idx) => {
                                                const isMine = s.status === 'LOCKED' && s.lockedByUserId === user.id;
                                                const isUnavailable = s.status === 'SOLD' || (s.status === 'LOCKED' && !isMine);
                                                const aisle = idx === 3 ? 'mr-4' : '';

                                                let btnStyle = 'bg-slate-700 border-slate-500 text-white hover:bg-slate-600';
                                                if (s.tier.includes('VIP')) btnStyle = 'bg-amber-500/80 border-amber-300 text-slate-950 hover:bg-amber-400';
                                                else if (s.tier.includes('Golden')) btnStyle = 'bg-cyan-500/80 border-cyan-300 text-slate-950 hover:bg-cyan-400';

                                                if (isMine) btnStyle = 'bg-emerald-500 border-2 border-white text-slate-950 font-extrabold scale-105 shadow-lg shadow-emerald-500/40';
                                                if (isUnavailable) btnStyle = 'bg-slate-800/50 border-slate-800 text-slate-600 cursor-not-allowed';

                                                return (
                                                    <button key={s.id} disabled={isUnavailable} onClick={() => handleSeatClick(s)} className={`w-9 h-9 rounded-lg border font-mono font-bold text-xs transition ${btnStyle} ${aisle}`}>
                                                        {s.seatIdentifier}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                        <span className="w-20 text-[11px] font-mono text-slate-400 pl-2">{rowSeats[0]?.price} RON</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                    <div className="mt-4 pt-3 border-t border-slate-800/80 flex items-center justify-between text-xs text-slate-400 font-mono">
                        <span>Concurrency: MySQL Pessimistic Row Lock</span>
                        <span>Gate Entry: Autonomous QR Turnstile</span>
                    </div>
                </div>

                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 sm:p-6 flex flex-col justify-between space-y-5">
                    <div className="space-y-4">
                        <h3 className="font-bold text-lg text-white border-b border-slate-800 pb-3">Reservation Summary</h3>
                        <div className="space-y-2 max-h-60 overflow-y-auto pr-1">
                            {myLockedSeats.length === 0 ? (
                                <p className="text-sm text-slate-400 italic py-6 text-center">No seats locked yet. Select up to 6 seats from the venue map.</p>
                            ) : (
                                myLockedSeats.map(s => (
                                    <div key={s.id} className="flex items-center justify-between bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5">
                                        <div>
                                            <p className="text-xs font-bold text-white">Seat {s.seatIdentifier} <span className="text-cyan-400 font-normal">• {s.tier}</span></p>
                                            <p className="text-[11px] font-mono text-emerald-400">Row Lock Acquired</p>
                                        </div>
                                        <div className="flex items-center gap-2.5">
                                            <span className="font-mono text-xs font-bold text-white">{s.price} RON</span>
                                            <button onClick={() => handleSeatClick(s)} className="text-slate-500 hover:text-rose-400 text-xs font-bold">✕</button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>

                    <div className="space-y-4 border-t border-slate-800 pt-4">
                        <div className="flex justify-between text-base font-bold text-white">
                            <span>Total Amount</span>
                            <span className="font-mono text-cyan-400">{totalAmount} RON</span>
                        </div>

                        <div className="grid grid-cols-2 gap-2">
                            <button type="button" onClick={() => setPaymentMethod('card')} className={`px-3 py-2 rounded-xl border text-xs font-semibold ${paymentMethod === 'card' ? 'border-cyan-500 bg-cyan-500/10 text-white' : 'border-slate-700 bg-slate-950 text-slate-300'}`}>
                                💳 Card (Visa/MC)
                            </button>
                            <button type="button" onClick={() => setPaymentMethod('apple')} className={`px-3 py-2 rounded-xl border text-xs font-semibold ${paymentMethod === 'apple' ? 'border-cyan-500 bg-cyan-500/10 text-white' : 'border-slate-700 bg-slate-950 text-slate-300'}`}>
                                📱 Apple / Google Pay
                            </button>
                        </div>

                        <button disabled={myLockedSeats.length === 0} onClick={handleCheckout} className={`w-full py-3.5 px-4 rounded-xl font-bold text-sm transition-all ${myLockedSeats.length === 0 ? 'bg-slate-800 text-slate-500 cursor-not-allowed' : 'bg-gradient-to-r from-cyan-500 to-emerald-500 hover:from-cyan-400 hover:to-emerald-400 text-slate-950 shadow-lg shadow-cyan-500/25'}`}>
                            {myLockedSeats.length === 0 ? 'Select Seats to Checkout' : `Pay ${totalAmount} RON & Generate QR Tickets`}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default InteractiveSeating;
